#include "tigersheets/main_window.hpp"
#include <QApplication>
#include <QTemporaryDir>
#include <QElapsedTimer>
#include <iostream>
using namespace tigersheets;
int main(int argc,char**argv){QApplication app(argc,argv);QTemporaryDir dir;qputenv("TIGERSHEETS_STATE_DIR",dir.path().toUtf8());MainWindow window;auto& session=window.currentSession();Json legacy={{"id","old"},{"staticSummary",true},{"source",{{"sheet","sheet-1"},{"row1",1},{"col1",1},{"row2",3},{"col2",2}}},{"rowField","Region"},{"valueField","Revenue"},{"aggregate","sum"},{"output",{{"sheet","sheet-1"},{"row",1},{"col",5}}}};Json operations=Json::array();const std::vector<std::vector<std::string>> rows={{"Region","Revenue"},{"East","8"},{"West","12"}};for(int r=0;r<3;++r)for(int c=0;c<2;++c)operations.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",r+1},{"col",c+1},{"input",rows[r][c]}});operations.push_back({{"type","set_cell"},{"sheet","sheet-1"},{"row",1},{"col",5},{"input","Original summary"}});operations.push_back({{"type","set_metadata"},{"key","pivots"},{"value",Json::array({legacy})}});if(!session.apply(0,operations))return 2;const auto before=session.snapshot();if(!window.executeCommand("pivot.convert",{{"id","old"}})){std::cerr<<"Legacy summaries need an explicit desktop conversion preview\n";return 1;}QElapsedTimer timer;timer.start();while(!session.hasPreview()&&window.property("reportBusy").toBool()&&timer.elapsed()<10000)app.processEvents();if(!session.hasPreview()||session.snapshotView()!=before){std::cerr<<"Conversion leaves the original workbook untouched until Accept: "<<window.lastError().toStdString();return 1;}if(!window.executeCommand("preview.discard")||session.snapshotView()!=before)return 1;if(!window.executeCommand("pivot.convert",{{"id","old"}}))return 1;timer.restart();while(!session.hasPreview()&&window.property("reportBusy").toBool()&&timer.elapsed()<10000)app.processEvents();if(!window.executeCommand("preview.accept")||session.snapshotView()["pivots"].size()!=1||session.snapshotView()["pivots"][0].value("version",0)!=1||session.cellAt("sheet-1",1,5)->at("input")!="Original summary"){std::cerr<<"Accept converts only metadata and adds one native report on a new sheet\n";return 1;}if(!window.executeCommand("undo")||session.snapshotView()["pivots"]!=before["pivots"]||session.snapshotView()["sheets"]!=before["sheets"]){std::cerr<<"One undo restores the legacy summary metadata and removes the native conversion\n";return 1;}std::cout<<"static conversion desktop tests passed\n";}
